38	function useCountUp(target: number, d = 900) {
39	  const [count, setCount] = useState(0);
40	  useEffect(() => {
41	    const start = performance.now();
42	    let f: number;
43	    const tick = (now: number) => {
44	      const p = Math.min((now - start) / d, 1);
45	      setCount(Math.round((1 - (1 - p) ** 3) * target));
46	      if (p < 1) f = requestAnimationFrame(tick);
47	    };
48	    f = requestAnimationFrame(tick);
49	    return () => cancelAnimationFrame(f);
50	  }, [target, d]);
51	  return count;
52	}
