353	            <p className="text-[11px] font-semibold text-zinc-300 mb-3">Source Breakdown</p>
354	            <div className="space-y-2">
355	              {SOURCES.map((src) => {
356	                const count = packets.filter((p) => p.source === src).length;
357	                const pct = Math.max(5, (count / Math.max(packets.length, 1)) * 100);
358	                return (
359	                  <div key={src} className="flex items-center gap-3">
360	                    <span className="text-[10px] font-mono text-zinc-500 w-24 flex-shrink-0">
