362	                    </span>
363	                    <div className="flex-1 h-1 bg-white/[0.05] rounded-full overflow-hidden">
364	                      <div
365	                        className="h-full bg-blue-500/60 rounded-full transition-all duration-500"
366	                        style={{ width: `${pct}%` }}
367	                      />
368	                    </div>
369	                    <span className="text-[10px] font-mono text-zinc-600 tabular-nums w-8 text-right">
370	                      {count}
371	                    </span>
372	                  </div>
373	                );
374	              })}
375	            </div>
376	          </div>
377	        </div>
378	      </div>
379	    </div>
