                    </div>
                    <div className={`h-1 ${cfg.bar} rounded-full overflow-hidden`}>
                      <div
                        className={`h-full ${cfg.progress} rounded-full transition-all duration-700 ease-[cubic-bezier(0.32,0.72,0,1)]`}
