263	// ─── seamless video loop ──────────────────────────────────────────────
264	function SeamlessVideoLoop({ videos }: { videos: string[] }) {
265	  const aRef = useRef<HTMLVideoElement>(null);
266	  const bRef = useRef<HTMLVideoElement>(null);
267	  const [active, setActive] = useState<0 | 1>(0);
268	  const idxRef = useRef(0);
269	
270	  useEffect(() => {
271	    const a = aRef.current;
272	    const b = bRef.current;
273	    if (!a || !b) return;
274	
275	    const refs = [a, b] as const;
276	
277	    function advance(finished: 0 | 1) {
278	      const next = (finished === 0 ? 1 : 0) as 0 | 1;
279	      const nextIdx = (idxRef.current + 1) % videos.length;
280	      idxRef.current = nextIdx;
281	      refs[next].src = videos[nextIdx];
282	      refs[next].load();
283	      refs[next].play().catch(() => {});
284	      setActive(next);
285	
286	      const upcoming = (next === 0 ? 1 : 0) as 0 | 1;
287	      const upcomingIdx = (nextIdx + 1) % videos.length;
288	      refs[upcoming].src = videos[upcomingIdx];
289	      refs[upcoming].load();
290	    }
291	
292	    a.src = videos[0];
293	    b.src = videos[1 % videos.length];
294	    a.load();
295	    b.load();
296	    a.play().catch(() => {});
297	
298	    const onEndA = () => advance(0);
299	    const onEndB = () => advance(1);
300	    a.addEventListener("ended", onEndA);
301	    b.addEventListener("ended", onEndB);
302	    return () => {
303	      a.removeEventListener("ended", onEndA);
304	      b.removeEventListener("ended", onEndB);
305	    };
306	  }, [videos]);
307	
308	  const base = "absolute inset-0 w-full h-full object-cover transition-opacity duration-0";
309	  return (
310	    <>
311	      <video
312	        ref={aRef}
313	        className={base}
314	        style={{ opacity: active === 0 ? 0.45 : 0 }}
315	        muted
316	        playsInline
317	        preload="auto"
318	      />
319	      <video
320	        ref={bRef}
321	        className={base}
322	        style={{ opacity: active === 1 ? 0.45 : 0 }}
323	        muted
324	        playsInline
325	        preload="auto"
326	      />
327	    </>
328	  );
329	}
