34	function useCountUp(target: number, d = 900) {
35	  const [count, setCount] = useState(0);
36	  useEffect(() => {
37	    const start = performance.now();
38	    let f: number;
39	    const tick = (now: number) => {
40	      const p = Math.min((now - start) / d, 1);
41	      setCount(Math.round((1 - (1 - p) ** 3) * target));
42	      if (p < 1) f = requestAnimationFrame(tick);
43	    };
44	    f = requestAnimationFrame(tick);
45	    return () => cancelAnimationFrame(f);
46	  }, [target, d]);
47	  return count;
48	}
